import pandas as pd,numpy as np,warnings,itertools
warnings.filterwarnings('ignore')
from pymatgen.core import Composition,Element,Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor
from catboost import CatBoostRegressor
tr=pd.read_csv('nlo_shg_eg_train.csv');po=pd.read_csv('nlo_pool.csv');d=pd.concat([tr,po]);els=sorted(set().union(*[set(Composition(x).as_dict()) for x in d.formula]),key=lambda x:Element(x).Z)
props=['Z','atomic_mass','atomic_radius','X','row','group','mendeleev_no','molar_volume','melting_point','electron_affinity','ionization_energy']
def g(e,p):
 try:return float(getattr(e,p))
 except:return np.nan
med={p:np.nanmedian([g(Element(e),p) for e in els]) for p in props}
def feat(r):
 c=Composition(r.formula).fractional_composition;ee=[Element(e) for e in c.elements];w=np.array([c[e.symbol] for e in ee]);f=[c[e] for e in els]+[len(ee),-sum(w*np.log(w))]
 for p in props:
  a=np.array([g(e,p) for e in ee]);a=np.where(np.isnan(a),med[p],a);u=w@a;f += [u,np.sqrt(w@((a-u)**2)),min(a),max(a),np.ptp(a)]
 s=Structure.from_str(r.poscar,fmt='poscar');la=s.lattice
 try:sa=SpacegroupAnalyzer(s,symprec=.05);sg=sa.get_space_group_number();op=len(sa.get_symmetry_operations())
 except:sg=op=0
 return f+[np.log1p(len(s)),s.volume/len(s),s.density,min(la.abc)/max(la.abc),*la.angles,sg/230,np.log1p(op)]
X=np.array([feat(r) for _,r in d.iterrows()]);n=len(tr)
models={}
for typ in ['ET','RF','CB']:
 for trans in ['raw','log']:
  pp=[]
  for target in ['shg','band_gap']:
   y=tr[target].values; yy=np.log1p(y) if trans=='log' else y
   if typ=='ET':m=ExtraTreesRegressor(n_estimators=600,min_samples_leaf=2,max_features=.7,n_jobs=-1,random_state=7)
   elif typ=='RF':m=RandomForestRegressor(n_estimators=600,min_samples_leaf=2,max_features=.7,n_jobs=-1,random_state=7)
   else:m=CatBoostRegressor(iterations=700,depth=5,learning_rate=.03,l2_leaf_reg=5,verbose=False,random_seed=7)
   z=m.fit(X[:n],yy).predict(X[n:]);pp.append(np.expm1(z) if trans=='log' else z)
  models[typ+trans]=pp
def hv(ids,x,y):
 q=sorted([(x[i],y[i]) for i in ids],reverse=True); ym=0;s=0
 for xx,yy in q:
  if yy>ym:s+=xx*(yy-ym);ym=yy
 return s
def solve(x,y):
 par=[i for i in range(100) if not any(x[j]>=x[i] and y[j]>=y[i] and (x[j]>x[i] or y[j]>y[i]) for j in range(100))]
 best=max(itertools.combinations(par,min(5,len(par))),key=lambda z:hv(z,x,y))
 return hv(best,x,y),best,par
for name,(x,y) in models.items():
 h,b,p=solve(x,y);print(name,round(h,2),'OPT',[(po.iloc[i].candidate_id,round(x[i],1),round(y[i],2)) for i in b]);print('PARETO',[(po.iloc[i].candidate_id,round(x[i],1),round(y[i],2)) for i in sorted(p,key=lambda z:-x[z])])
# selected high-gap predictions all models
ids=['c023','c025','c030','c037','c051','c052','c053','c055','c057','c058','c059','c073','c081','c084','c085','c090','c091']
print('\nFOCUS')
for cid in ids:
 i=po.index[po.candidate_id==cid][0]; print(cid,po.iloc[i].formula,' | ',' '.join(f'{k}:{v[0][i]:.1f}/{v[1][i]:.2f}' for k,v in models.items()))
